def calistir(program: str):
    """
    Basit bir hesap dilini yorumlar ve son ifadenin değerini döndürür.
    eval, exec, compile ve ast kullanılmaz.
    """

    satirlar = program.split('\n')
    # Her satırı işle ve yorumları çıkar
    temiz_satirlar = []
    for satir in satirlar:
        # Satır sonundan önceki yorumu bul (# işaretinden sonra kalan her şey)
        if '#' in satir:
            satir = satir[:satir.index('#')]
        # Satırı boşluqlardan temizle
        satir = satir.strip()
        # Satır sonundan ';' varsa çıkar
        if satir.endswith(';'):
            satir = satir[:-1].strip()
        # Boş ifadeleri yok say
        if satir == '':
            continue
        temiz_satirlar.append(satir)

    # Tüm satırları tek bir satırda birleştir
    program = ' '.join(temiz_satirlar)

    # Programı ifadelere ayır (satır sonu veya ; ile)
    # Önce ; ile ayır
    if ' ' not in program and ';' in program:
        program = program.replace(';', ' ')
    # Satır sonu ayırıcısını ekle (artık tek bir satır olduğu için)
    # aslında daha önce tüm satırları birleştirdik, bu yüzden sadece ; kaldı
    # Ancak orijinal satır sonları da olabilir, onları da ekle
    # Daha iyi bir yaklaşım: orijinal programı parça parça oku

    # Programı ifadelere ayır
    ifadeler = []
    calistir = ''
    i = 0
    while i < len(program):
        # Satır sonu bul
        if program[i:i+2] == '\n':
            if calistir.strip():
                ifadeler.append(calistir.strip())
            calistir = ''
            i += 2
        elif program[i] == ';':
            if calistir.strip():
                ifadeler.append(calistir.strip())
                calistir = ''
            i += 1
        elif program[i].isspace():
            if calistir.strip():
                ifadeler.append(calistir.strip())
                calistir = ''
            i += 1
        else:
            calistir += program[i]
            i += 1
