        ifadeler.append(calistir.strip())

    # Değişkenleri sakla
    degiskenler = {}

    # Sonuç
    sonuc = None

    # Her ifadeyi parse et ve çalıştır
    for ifade in ifadeler:
        try:
            sonuc = parse_calistir(ifade, degiskenler)
        except ZeroDivisionError:
            raise
        except (NameError, SyntaxError):
            raise
        except Exception as e:
            # Bilinmeyen fonksiyon veya tanımsız değişken için NameError at
            if not isinstance(e, (ZeroDivisionError, NameError, SyntaxError)):
                # SyntaxError veya NameError gibi davran
                raise NameError(str(e))

    return sonuc


