    # Önce atama kontrol et: ad = ifade
    if '=' in ifade:
        # Parantez kontrolü: (ad = ...) gibi
        parantez_denge = 0
        atama_bulundu = False
        atama_baslangic = -1

        for i, c in enumerate(ifade):
