            if self.text[i] == ')':
                tokens.append(')')
                i += 1
                continue
            # Varsayılan: değişken veya operatör
            if self.text[i] in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_':
                j = i
