                self.advance()
                args.append(self.expr())
        if self.peek() != ')':
            raise SyntaxError(f"{name} fonksiyonu kapanan parantez bekliyor")
        self.advance()
        # Fonksiyonu uygula
        if name == 'min':
            return min(*[self.eval_var(a) for a in args])
        elif name == 'max':
            return max(*[self.eval_var(a) for a in args])
        elif name == 'abs':
            return abs(self.eval_var(args[0]))

    def eval_var(self, val):
        if isinstance(val, (int, float)):
            return val
        if isinstance(val, str):
            return self.eval_var(val)
        if isinstance(val, tuple):
            # (expr, op, expr) -> (lhs, op, rhs)
            return self.eval_val(val)

    def eval_val(self, expr):
        if isinstance(expr, tuple):
            lhs, op, rhs = expr
            lhs = self.eval_val(lhs)
            rhs = self.eval_val(rhs)
            if op == '+':
                return lhs + rhs
            elif op == '-':
                return lhs - rhs
            elif op == '*':
                return lhs * rhs
            elif op == '/':
                return lhs / rhs
            elif op == '%':
                return lhs % rhs
            elif op == '**':
                return lhs ** rhs
        return expr


class Interpreter:
    def __init__(self, text: str):
        self.text = text
        self.variables: dict = {}

    def tokenize(self) -> List[str]:
        return Tokenizer(self.text).tokenize()

    def parse(self, tokens: List[str]) -> Tuple:
        parser = Parser(tokens)
        return parser.expr()

    def eval_var(self, expr):
        if isinstance(expr, (int, float)):
            return expr
        if isinstance(expr, str):
            if expr in self.variables:
                return self.variables[expr]
            raise NameError(f"Tanımsız değişken: {expr}")
        return self.eval_val(expr)

    def eval_val(self, expr):
        if isinstance(expr, tuple):
            lhs, op, rhs = expr
            lhs = self.eval_val(lhs)
            rhs = self.eval_val(rhs)
            if op == '+':
                return lhs + rhs
            elif op == '-':
                return lhs - rhs
            elif op == '*':
                return lhs * rhs
            elif op == '/':
                if isinstance(rhs, (int, float)) and rhs == 0:
                    raise ZeroDivisionError("Sıfıra bölme")
                return lhs / rhs
            elif op == '%':
                if isinstance(rhs, (int, float)) and rhs == 0:
                    raise ZeroDivisionError("Sıfıra bölme")
                return lhs % rhs
            elif op == '**':
                return lhs ** rhs
        return expr

    def run(self) -> Any:
        if not self.text.strip():
            return None
        tokens = self.tokenize()
        # Atamaları ve ifadeleri ayır
        statements = self.split_statements(tokens)
        for stmt in statements:
            result = self.run_stmt(stmt)
            if isinstance(result, tuple):
                # (name, value) -> assignment
                if result[0] not in self.variables:
                    raise NameError(f"Tanımsız değişken: {result[0]}")
                self.variables[result[0]] = result[1]
            else:
                # Expression result
                if result is not None:
                    return result
        return None

    def split_statements(self, tokens: List[str]) -> List[str]:
        statements = []
        current = []
        paren_depth = 0
        in_comment = False
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            if tok in ['(', ')']:
                paren_depth += 1 if tok == '(' else -1
                current.append(tok)
            elif tok in ['+', '-', '*', '/', '%', '.']:
                current.append(tok)
            elif tok == ';':
                if current and any(t in ['+', '-', '*', '/', '%'] for t in current):
                    statements.append(' '.join(current))
                    current = []
                elif current:
                    statements.append(' '.join(current))
                    current = []
            elif tok == ',':
                if paren_depth == 0 and current:
                    # Argüman ayırıcısı, yeni ifade olarak al
                    statements.append(' '.join(current))
                    current = []
            elif tok == '#':
                # Satır sonuna kadar boşalt
                while i < len(tokens) and tokens[i] != ';':
                    i += 1
                continue
            else:
                current.append(tok)
            i += 1
        if current:
            statements.append(' '.join(current))
        return statements

    def run_stmt(self, stmt: str):
        tokens = Tokenizer(stmt).tokenize()
        parsed = self.parse(tokens)
        return parsed

    def calistir(self, program: str) -> Any:
        if not program.strip():
            return None
        return self.run()


def calistir(program: str) -> Any:
    interpreter = Interpreter(program)
    return interpreter.calistir(program)


